var __index = {"config":{"lang":["en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"\u6b22\u8fce\uff01","text":"<p>\u8fd9\u662f\u4e00\u4e2a\u5efa\u7acb\u51e0\u4e2a\u6708\u7684(\u6682\u65f6\u88ab\u5e9f\u5f03\u7684)\u4e3b\u9875</p>"},{"location":"say.html","title":"\u60f3\u8bf4\u7684\u8bdd","text":"<p>      \u4f60\u770b\u770b           \u518d\u770b\u770b       \u8fd9\u5176\u5b9e\u662f\u4e00\u4e2a\u7a7a\u67b6\u5b50</p>"},{"location":"vibecoding.html","title":"Vibe Coding \u7b14\u8bb0","text":"<p>Vibe Coding \u4e0d\u662f\u201c\u8ba9 AI \u66ff\u6211\u5199\u5b8c\u6240\u6709\u4ee3\u7801\u201d\uff0c\u800c\u662f\u4e00\u79cd\u66f4\u5feb\u7684\u521b\u4f5c\u65b9\u5f0f\uff1a\u4eba\u8d1f\u8d23\u65b9\u5411\u3001\u5224\u65ad\u548c\u9a8c\u6536\uff0cAI \u8d1f\u8d23\u628a\u60f3\u6cd5\u5feb\u901f\u5c55\u5f00\u6210\u53ef\u8fd0\u884c\u7684\u8349\u7a3f\u3002</p> <p>\u5b83\u9002\u5408\u4ece\u96f6\u5f00\u59cb\u505a\u539f\u578b\u3001\u5199\u811a\u672c\u3001\u642d\u5efa\u5c0f\u5de5\u5177\u3001\u6574\u7406\u5df2\u6709\u4ee3\u7801\u3001\u8865\u6d4b\u8bd5\u3001\u6539\u4ea4\u4e92\u7ec6\u8282\u3002\u5b83\u4e0d\u9002\u5408\u5b8c\u5168\u653e\u5f03\u7406\u89e3\uff0c\u4e5f\u4e0d\u9002\u5408\u628a\u6ca1\u6709\u9a8c\u8bc1\u8fc7\u7684\u4ee3\u7801\u76f4\u63a5\u4e22\u8fdb\u751f\u4ea7\u73af\u5883\u3002</p>"},{"location":"vibecoding.html#_1","title":"\u6838\u5fc3\u611f\u89c9","text":"<p>\u4f20\u7edf\u5199\u4ee3\u7801\u50cf\u662f\u4e00\u884c\u4e00\u884c\u780c\u5899\u3002Vibe Coding \u66f4\u50cf\u662f\u5728\u548c\u4e00\u4e2a\u5f88\u5feb\u7684\u642d\u6863\u5bf9\u8bdd\uff1a</p> <ol> <li>\u5148\u63cf\u8ff0\u60f3\u8981\u7684\u6548\u679c\u3002</li> <li>\u8ba9 AI \u7ed9\u51fa\u7b2c\u4e00\u7248\u5b9e\u73b0\u3002</li> <li>\u8fd0\u884c\u3001\u89c2\u5bdf\u3001\u6307\u51fa\u54ea\u91cc\u4e0d\u5bf9\u3002</li> <li>\u7ee7\u7eed\u6536\u7a84\u9700\u6c42\uff0c\u76f4\u5230\u7ed3\u679c\u53ef\u7528\u3002</li> </ol> <p>\u8fd9\u4e2a\u8fc7\u7a0b\u7684\u91cd\u70b9\u4e0d\u662f\u201c\u63d0\u793a\u8bcd\u6709\u591a\u795e\u201d\uff0c\u800c\u662f\u53cd\u9988\u5faa\u73af\u8db3\u591f\u77ed\u3002\u53ea\u8981\u80fd\u5feb\u901f\u770b\u5230\u7ed3\u679c\uff0c\u5c31\u80fd\u5feb\u901f\u4fee\u6b63\u65b9\u5411\u3002</p>"},{"location":"vibecoding.html#_2","title":"\u4e00\u4e2a\u53ef\u7528\u6d41\u7a0b","text":"<p>\u5148\u5199\u6e05\u695a\u76ee\u6807\uff1a</p> <p>\u6211\u60f3\u505a\u4ec0\u4e48\uff1f\u7528\u6237\u770b\u5230\u4ec0\u4e48\uff1f\u8f93\u5165\u662f\u4ec0\u4e48\uff1f\u8f93\u51fa\u662f\u4ec0\u4e48\uff1f\u4ec0\u4e48\u60c5\u51b5\u7b97\u5b8c\u6210\uff1f</p> <p>\u518d\u8ba9 AI \u751f\u6210\u6700\u5c0f\u7248\u672c\u3002\u4e0d\u8981\u4e00\u5f00\u59cb\u5c31\u8981\u6c42\u67b6\u6784\u5b8c\u7f8e\uff0c\u5148\u8ba9\u5b83\u8dd1\u8d77\u6765\u3002</p> <p>\u63a5\u7740\u81ea\u5df1\u8fd0\u884c\u548c\u68c0\u67e5\u3002\u770b\u5230\u62a5\u9519\u5c31\u628a\u5b8c\u6574\u62a5\u9519\u7ed9 AI\uff0c\u770b\u5230\u4f53\u9a8c\u95ee\u9898\u5c31\u63cf\u8ff0\u5177\u4f53\u753b\u9762\u548c\u9884\u671f\u3002\u4e0d\u8981\u53ea\u8bf4\u201c\u4e0d\u597d\u7528\u201d\uff0c\u8981\u8bf4\u201c\u6309\u94ae\u592a\u9760\u4e0b\u201d\u201c\u79fb\u52a8\u7aef\u6587\u5b57\u91cd\u53e0\u201d\u201c\u4fdd\u5b58\u540e\u6ca1\u6709\u63d0\u793a\u201d\u3002</p> <p>\u6700\u540e\u505a\u6536\u5c3e\uff1a</p> <ul> <li>\u5220\u9664\u6ca1\u7528\u7684\u4ee3\u7801\u3002</li> <li>\u7edf\u4e00\u547d\u540d\u548c\u683c\u5f0f\u3002</li> <li>\u8865\u4e0a\u5173\u952e\u6d4b\u8bd5\u3002</li> <li>\u81ea\u5df1\u8bfb\u4e00\u904d\u6838\u5fc3\u903b\u8f91\u3002</li> <li>\u786e\u8ba4\u6ca1\u6709\u628a\u5bc6\u94a5\u3001\u9690\u79c1\u6570\u636e\u6216\u4e34\u65f6\u4ee3\u7801\u63d0\u4ea4\u8fdb\u53bb\u3002</li> </ul>"},{"location":"vibecoding.html#_3","title":"\u63d0\u793a\u8bcd\u5199\u6cd5","text":"<p>\u6709\u6548\u7684\u63d0\u793a\u8bcd\u901a\u5e38\u5305\u542b\u56db\u4ef6\u4e8b\uff1a</p> <ul> <li>\u80cc\u666f\uff1a\u73b0\u5728\u9879\u76ee\u662f\u4ec0\u4e48\uff0c\u76f8\u5173\u6587\u4ef6\u5728\u54ea\u91cc\u3002</li> <li>\u76ee\u6807\uff1a\u8981\u5b9e\u73b0\u4ec0\u4e48\u7ed3\u679c\u3002</li> <li>\u7ea6\u675f\uff1a\u4e0d\u80fd\u6539\u4ec0\u4e48\uff0c\u5fc5\u987b\u4fdd\u6301\u4ec0\u4e48\u98ce\u683c\u3002</li> <li>\u9a8c\u6536\uff1a\u600e\u6837\u5224\u65ad\u5b8c\u6210\u3002</li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>\u5728\u73b0\u6709 MkDocs \u7b14\u8bb0\u7ad9\u91cc\u65b0\u589e\u4e00\u7bc7\u4e2d\u6587\u7b14\u8bb0\u3002\n\u6587\u4ef6\u653e\u5728 docs/\uff0c\u5e76\u628a\u5b83\u52a0\u5165 mkdocs.yml \u7684 nav\u3002\n\u4fdd\u6301\u5f53\u524d\u7ad9\u70b9\u98ce\u683c\uff0c\u4e0d\u8981\u6539\u4e3b\u9898\u914d\u7f6e\u3002\n\u5b8c\u6210\u540e\u8fd0\u884c mkdocs build \u9a8c\u8bc1\u3002\n</code></pre> <p>\u8d8a\u5177\u4f53\uff0cAI \u8d8a\u50cf\u5de5\u5177\uff1b\u8d8a\u6a21\u7cca\uff0cAI \u8d8a\u50cf\u5728\u731c\u3002</p>"},{"location":"vibecoding.html#_4","title":"\u9700\u8981\u4fdd\u7559\u4eba\u7684\u5224\u65ad","text":"<p>Vibe Coding \u6700\u5bb9\u6613\u51fa\u95ee\u9898\u7684\u5730\u65b9\uff0c\u662f\u628a\u201c\u751f\u6210\u5f97\u5f88\u5feb\u201d\u8bef\u8ba4\u4e3a\u201c\u7ed3\u679c\u662f\u5bf9\u7684\u201d\u3002</p> <p>AI \u53ef\u80fd\u4f1a\u5199\u51fa\u80fd\u8fd0\u884c\u4f46\u4e0d\u5408\u7406\u7684\u4ee3\u7801\uff0c\u4e5f\u53ef\u80fd\u4f1a\u7f16\u51fa\u4e0d\u5b58\u5728\u7684 API\uff0c\u8fd8\u53ef\u80fd\u5728\u4fee bug \u65f6\u987a\u624b\u6539\u574f\u522b\u7684\u5730\u65b9\u3002\u6240\u4ee5\u4eba\u5fc5\u987b\u4fdd\u7559\u51e0\u4e2a\u52a8\u4f5c\uff1a</p> <ul> <li>\u8bfb\u5173\u952e\u8def\u5f84\u4ee3\u7801\u3002</li> <li>\u8dd1\u6d4b\u8bd5\u6216\u624b\u52a8\u9a8c\u8bc1\u6838\u5fc3\u6d41\u7a0b\u3002</li> <li>\u770b git diff\uff0c\u786e\u8ba4\u4fee\u6539\u8303\u56f4\u7b26\u5408\u9884\u671f\u3002</li> <li>\u5bf9\u5b89\u5168\u3001\u6570\u636e\u3001\u6743\u9650\u3001\u652f\u4ed8\u7b49\u9ad8\u98ce\u9669\u4f4d\u7f6e\u4fdd\u6301\u8c28\u614e\u3002</li> </ul>"},{"location":"vibecoding.html#_5","title":"\u6211\u7684\u4f7f\u7528\u539f\u5219","text":"<p>\u6211\u66f4\u613f\u610f\u628a Vibe Coding \u5f53\u6210\u201c\u52a0\u901f\u5668\u201d\uff0c\u4e0d\u662f\u201c\u81ea\u52a8\u9a7e\u9a76\u201d\u3002</p> <p>\u5b83\u53ef\u4ee5\u5e2e\u6211\u8de8\u8fc7\u7a7a\u767d\u9875\uff0c\u53ef\u4ee5\u628a\u60f3\u6cd5\u53d8\u6210\u7b2c\u4e00\u7248\uff0c\u53ef\u4ee5\u66ff\u6211\u505a\u91cd\u590d\u52b3\u52a8\u3002\u4f46\u6700\u7ec8\u6211\u4ecd\u7136\u8981\u77e5\u9053\u8fd9\u4e2a\u4e1c\u897f\u4e3a\u4ec0\u4e48\u80fd\u8dd1\u3001\u54ea\u91cc\u53ef\u80fd\u574f\u3001\u4ee5\u540e\u600e\u4e48\u7ef4\u62a4\u3002</p> <p>\u6700\u8212\u670d\u7684\u72b6\u6001\u662f\uff1a\u6211\u4e0d\u518d\u88ab\u8bed\u6cd5\u548c\u6837\u677f\u4ee3\u7801\u62d6\u4f4f\uff0c\u4f46\u4ecd\u7136\u638c\u63e1\u65b9\u5411\u76d8\u3002</p>"}]}